		if (response == null)
			response = inforesponse = new ResponseInfo();
	}

	/* @Override */
	public void saveXml(Writer fwrite)
    {
		fwrite.append('<').append(name);
		fwrite.append(" template=\"").append(config_template).append("\">\n");
